function storedIdentity(){return {instanceId:CID,workerSha256:H('stored-worker-original'),runtimeSha256:H('stored-runtime-original'),heartbeatAt:'2026-10-09T13:23:00.000Z',expiresAt:'2026-10-09T13:24:00.000Z'};}
function payload(){return {checkedAt:'2026-10-09T13:25:00.000Z',storedIdentity:storedIdentity(),deployment:{present:true,enabled:true,approvalPresent:true,approvalTiming:'effective',queryExpected:true},lease:{present:true,live:false,suspended:false,reason:null},deploymentLeaseMatch:{worker:true,runtime:true,databaseRole:true},selection:{present:true,enabled:false,queryExpected:true,verifiedAt:'2026-10-09T13:24:00.000Z'}};}
function catalog(){return Object.entries(core.COLUMN_TYPES).map(([relation,types])=>({relation,kind:'r',readable:true,columns:Object.entries(types).map(([name,oid])=>({name,oid,typmod:-1}))}));}
function dependencies(){return {workerRoleKnown:true,relations:Object.entries(core.SCANNER_COLUMNS).map(([name,cols])=>({name,present:true,kind:'table',rowSecurity:false,forcedRowSecurity:false,allCampaignColumnsSelect:name==='campaigns'?true:null,columns:Object.keys(cols).map(name2=>({name:name2,present:true,typeCompatible:true,readerSelect:true,workerSelect:true,workerUpdate:name==='campaigns'&&['sent','to_send','status','max_subscriber_id','started_at'].includes(name2)?true:null}))})),functions:core.SCANNER_FUNCTIONS.map(name=>({name,present:true,signatureCompatible:true,workerExecute:true,volatility:'stable',securityDefiner:false})),activityCapability:{readable:true,visible:false}};}
function shapes(){return {observedCount:2,truncated:false,runningCount:0,dueCount:2,attribsTopLevelIncompatible:0,headersIncompatible:0,headersUnknown:0,tagsIncompatible:0,scalarNullIncompatible:0,timestampIncompatible:0,targets:[171,174].map(id=>({id,observed:true,attribsTopLevelCompatible:true,headersCompatible:true,tagsCompatible:true,nonNullableScalarsCompatible:true,finiteTimestampsCompatible:true}))};}
function activity(){return {connectionCount:2,activeCount:1,scannerPrefixMatchCount:1,scannerPrefixWaitingCount:1,maxPrefixAgeSeconds:10,ageCapped:false,states:[{name:'active',count:1},{name:'idle',count:1}],waits:[{name:'Lock',count:1},{name:'Client',count:1}]};}
function selectorFence(){return {sameRole:false,helpers:core.SELECTOR_FUNCTIONS.map(f=>({name:f.name,present:true,purePin:true,executable:true,actualProsrcSha256:f.prosrcSha256,actualProsrcBytes:core.SELECTOR_BODY_BYTES[f.name],matches:Object.fromEntries(core.PURE_PIN_FIELDS.map(k=>[k,true]))})),relations:core.SELECTOR_RELATIONS.map(r=>({name:r.name,present:true,compatible:true,readable:true})),updateGuard:{present:true,variant:'operation',contractMatches:true,triggerPresent:true,triggerEnabled:true,triggerMatches:true,actualProsrcSha256:core.SEND_GUARD_HASHES.operation,actualProsrcBytes:core.SEND_GUARD_BODY_BYTES.operation}};}
function selectorPayload(){return {checkedAt:'2026-10-09T13:25:00.000Z',targets:[171,174].map(id=>({id,eligible:true,contextReady:true,bound:false,templateCompatible:true,mediaCompatible:true,countPresent:true,countWithinInt32:true,eligibleCount:2,cursorCompatible:true}))};}
function contextGates(){return {checkedAt:'2026-10-09T13:25:00.000Z',targets:[171,174].map(id=>({id,bindingPresent:false,boundEffective:false,...Object.fromEntries(core.CONTEXT_FLAGS.map(k=>[k,null]))}))};}
function fixture(){
 const env={calls:[],clients:[],options:[],time:NOW,revoked:false,key:'disposable-fixture-key',mod:{},browser:[],bearer:'disposable-fixture-bearer'};
 const db=new DatabaseSync(':memory:');db.exec('PRAGMA foreign_keys=ON;CREATE TABLE users(id TEXT PRIMARY KEY);CREATE TABLE crm_native_connections_v1(id TEXT PRIMARY KEY,scopes_json TEXT);CREATE TABLE crm_native_delivery_health_consent_v1(purpose TEXT,receipt TEXT);CREATE TABLE crm_scheduler_read_consent_v1(purpose TEXT,receipt TEXT);');db.prepare('INSERT INTO users VALUES(?)').run(OWNER);for(const id of [CID,CID2])db.prepare('INSERT INTO crm_native_connections_v1 VALUES(?,?)').run(id,JSON.stringify(['crm.read','crm.delivery-health']));db.prepare('INSERT INTO crm_native_delivery_health_consent_v1 VALUES(?,?)').run('crm.delivery-health','accepted-health');db.prepare('INSERT INTO crm_scheduler_read_consent_v1 VALUES(?,?)').run('crm.scheduler-diagnostic','accepted-diagnostic');
 env.credential={schema:'shrigma-private-database-credential-v1',revision:1,ownerId:OWNER,username:'disposable_fixture_reader',password:'secret-never-in-output',resource:{...core.RESOURCE},transport:{mode:'admitted-private-network'}};
 env.context={nativeBearer:env.bearer,method:'GET'};env.browserContext={method:'POST',session:'valid-fixture-session',csrf:'valid-fixture-csrf'};
 const current=(context,id,browser)=>{env.browser.push(browser);assert.ok([CID,CID2].includes(id));if(env.revoked||env.vaultRevoked)throw Error('secret-current-denied');if(browser){assert.equal(context.session,'valid-fixture-session');assert.equal(context.csrf,'valid-fixture-csrf');assert.equal(context.method,'POST');}else assert.ok(context.nativeBearer===env.bearer||context.session==='valid-fixture-session');return {ownerId:OWNER,ownerRevision:H('owner-live'),connectionHash:H(id+'connection'),crmBindingHash:H('original-two-brand-bindings'),profileRevision:mac('real-fixture-mac','auth-profile-revision'),credentialBindingHash:core.credentialBinding(env.credential),resourceHash:core.resourceHash,queryHash:core.queryHash,...env.mod};};
 env.consent=createSchedulerStateConsent({db,current,mac:v=>mac(env.key,v),now:()=>env.time});
 class Client extends EventEmitter{
  constructor(options){super();env.options.push(options);env.clients.push(this);this.connection=new EventEmitter();this.connection.stream={encrypted:false};this.processID=41;}
  async connect(){env.calls.push('connect');if(env.connectError)throw Error('private-connect-error');this.connection.emit('readyForQuery',{status:'I'});}
  async query(sql){env.calls.push(sql);if(env.onQuery)await env.onQuery(sql);if(env.throwSQL===sql)throw Error('private-sql-error '+env.credential.password);let command='SELECT',status='I',rows=[];if(env.sqlstate&&sql===(env.errorSQL||core.DELIVERY_CONTROL_SQL)){if(!env.missingErrorACK){if(env.lateErrorACK)setImmediate(()=>this.connection.emit('readyForQuery',{status:'E'}));else this.connection.emit('readyForQuery',{status:env.errorACK||'E'});}if(env.doubleErrorACK)this.connection.emit('readyForQuery',{status:'E'});throw Object.assign(Error('private-error-query-body '+env.credential.password),{code:env.sqlstate});}
   if(sql===core.PEER)rows=[{database:'listmonk',sessionRole:env.credential.username,currentRole:env.credential.username,pid:41,port:5432,engine:170005,ssl:false,read_only:'on',...env.peer}];
   else if(sql===core.BEGIN){command='BEGIN';status='T';}
   else if(sql===core.CATALOG_SQL){status='T';rows=env.catalog||catalog();}
   else if(sql===core.READ_SQL){status='T';rows=env.rows||[{payload:env.payload||payload()}];}
   else if(sql===core.DEPENDENCY_SQL){status='T';rows=env.dependencyRows||[{payload:env.dependencies||dependencies()}];}
   else if(sql===core.SHAPES_SQL){status='T';rows=env.shapeRows||[{payload:env.shapes||shapes()}];}
   else if(sql===core.ACTIVITY_SQL){status='T';rows=env.activityRows||[{payload:env.activity||activity()}];}
   else if(sql===core.SELECTOR_FENCE_SQL){status='T';rows=env.fenceRows||[{payload:env.fence||selectorFence()}];}
   else if(sql===core.CONTEXT_GATES_SQL){status='T';rows=[{payload:env.contextGates||contextGates()}];}
   else if(sql===core.DELIVERY_FENCE_SQL){status='T';rows=[{payload:env.deliveryFence||deliveryFence()}];}
   else if(sql===core.DELIVERY_MATERIAL_SQL){status='T';rows=[{payload:env.deliveryMaterial||deliveryMaterial()}];}
   else if(sql===core.DELIVERY_CONTROL_SQL){status='T';rows=env.deliveryRows||[{payload:env.deliveryPayload||deliveryPayload()}];}
   else if(sql===core.ROLLBACK)command='ROLLBACK';
   else throw Error('arbitrary query refused in test fixture');
   this.connection.emit('readyForQuery',{status:env.badStatusSQL===sql?'E':status});if(env.doubleACKSQL===sql)this.connection.emit('readyForQuery',{status});
   return {command:env.badCommandSQL===sql?'UPDATE':command,rows,rowCount:command==='SELECT'?rows.length:null};
  }
  async end(){env.calls.push('end');if(env.onEnd)await env.onEnd();if(env.endError)throw Error('private-close-error '+env.credential.password);if(!env.missingEnd)this.emit('end');}
 }
 env.driver={Client,version:'8.23.1',packageSha256:H('disposable-pg-package')};
 env.auth={nativeSchedulerStateConsent:env.consent,nativeDatabaseVault:{getPrivateCredential:({ownerId})=>{assert.equal(ownerId,OWNER);if(env.vaultRevoked)throw Error('private-db-credential-revoked');return {...env.credential};}},nativeConnections:{authenticate:(token,needs)=>{assert.equal(needs.scope,'crm.read');if(token!==env.bearer||env.connectionRevoked)throw Error('private-native-token');return {id:CID};}}};
 env.controller=createSchedulerStateController({enabled:true,driver:env.driver,auth:env.auth,now:()=>env.time});
 env.authorize=(id=CID)=>env.consent.authorize({context:env.browserContext,connectionId:id,consent:true});
 env.read=()=>env.controller.nativeReadReceipt({context:env.context});env.finish=async()=>{try{await env.controller.close();}catch{}db.close();};env.db=db;return env;
}
function assertNoSecrets(value){const s=JSON.stringify(value);for(const word of ['secret-never-in-output','disposable_fixture_reader','approved_by','instance_id','private-sql-error','private-close-error','comunicacao_postgres'])assert.ok(!s.includes(word),word);}
test('dedicated consent refuses a boolean grant and prior purposes before PG',async()=>{const e=fixture();try{await assert.rejects(e.read(),{code:'SCHEDULER_STATE_SEPARATE_CONSENT_REQUIRED'});assert.deepEqual(e.calls,[]);assert.throws(()=>e.consent.authorize({context:e.browserContext,connectionId:CID,consent:false}),{code:'SCHEDULER_STATE_BROWSER_CONSENT_REQUIRED'});assert.throws(()=>e.consent.authorize({context:e.context,connectionId:CID,consent:true}),{code:'SCHEDULER_STATE_BROWSER_CONSENT_REQUIRED'});assert.equal(e.consent.status({context:e.context,connectionId:CID}).consented,false);assert.ok(e.browser.every(x=>typeof x==='boolean'));}finally{await e.finish();}});
test('authorize and invalidate alone request browser CURRENT; scopes and old consents stay byte equal',async()=>{const e=fixture();try{const before=e.db.prepare('SELECT * FROM crm_native_connections_v1 ORDER BY id').all();assert.equal(e.authorize().authorized,true);assert.equal(e.consent.status({context:e.context,connectionId:CID}).consented,true);const proof=e.consent.require({context:e.context,connectionId:CID});assert.match(proof.profileRevision,/^[a-f0-9]{64}$/);assert.equal(Object.keys(proof).length,8);assert.ok(Object.isFrozen(proof));assert.deepEqual(e.db.prepare('SELECT * FROM crm_native_connections_v1 ORDER BY id').all(),before);assert.equal(e.db.prepare('SELECT receipt FROM crm_native_delivery_health_consent_v1').get().receipt,'accepted-health');assert.equal(e.db.prepare('SELECT receipt FROM crm_scheduler_read_consent_v1').get().receipt,'accepted-diagnostic');e.consent.invalidate({context:e.browserContext,connectionId:CID});assert.throws(()=>e.consent.require({context:e.context,connectionId:CID}),{code:'SCHEDULER_STATE_SEPARATE_CONSENT_REQUIRED'});assert.throws(()=>e.authorize(),{code:'SCHEDULER_STATE_CONSENT_REVOKED'});assert.deepEqual(e.calls,[]);}finally{await e.finish();}});
