test('fixed READONLY protocol confirms I-T-I, closure and returns stored-state-only DTO',async()=>{const e=fixture();try{e.authorize();const r=await e.read();assert.equal(r.status,200);assert.equal(r.body.schema,'shrigma-original-scheduler-stored-state-v6');assert.deepEqual(r.body.storedIdentity,storedIdentity());assert.ok(Object.isFrozen(r.body.storedIdentity));assert.equal(r.body.storedStateOnly,true);assert.equal(r.body.runtimeMeasured,false);assert.equal(r.body.causeEstablished,false);assert.equal(r.body.authorizesSend,false);assert.deepEqual(e.calls,['connect',core.PEER,core.BEGIN,core.CATALOG_SQL,core.READ_SQL,core.DEPENDENCY_SQL,core.SHAPES_SQL,core.SELECTOR_FENCE_SQL,core.ROLLBACK,'end']);assert.match(e.options[0].options,/default_transaction_read_only=on/);assert.equal(e.options[0].pipeline,false);assert.equal(e.options[0].statement_timeout,10000);assertNoSecrets(r);assert.ok(Object.isFrozen(r.body.lease));assert.equal(core.queryHash,H([core.PEER,core.BEGIN,core.CATALOG_SQL,core.READ_SQL,core.DEPENDENCY_SQL,core.SHAPES_SQL,core.ACTIVITY_SQL,core.SELECTOR_FENCE_SQL,core.CONTEXT_GATES_SQL,core.DELIVERY_FENCE_SQL,core.DELIVERY_CONTROL_SQL,core.DELIVERY_MATERIAL_SQL,core.SELECTOR_SQL,core.canonical(core.SELECTOR_PROTOCOL),core.ROLLBACK].join('\n')));for(const sql of [core.CATALOG_SQL,core.READ_SQL])assert.doesNotMatch(sql,/\b(?:INSERT|UPDATE|DELETE|CREATE|GRANT|LOCK|FOR\s+SHARE|heartbeat\s*\(|claim\s*\(|refresh\w*\s*\(|regular_worker_require\s*\()/i);}finally{await e.finish();}});
test('v4 diagnostic receipt is terminal after TTL; same native invocation reads once',async()=>{const e=fixture();try{e.authorize();const r=await e.read();e.payload={...payload(),checkedAt:'2026-10-09T13:40:00.000Z'};assert.strictEqual(await e.read(),r);assert.equal(e.clients.length,1);e.time+=600001;const fresh=await e.read();assert.equal(fresh.status,200);assert.strictEqual(fresh,r);assert.equal(e.clients.length,1);}finally{await e.finish();}});
test('native receipt concurrent invocation never creates a second SELECT or client',async()=>{const e=fixture();let release,entered;const waiting=new Promise(resolve=>entered=resolve),hold=new Promise(resolve=>release=resolve);try{e.authorize();e.onQuery=async sql=>{if(sql===core.READ_SQL){entered();await hold;}};const first=e.read();await waiting;assert.deepEqual(await e.read(),{status:409,body:{error:'SCHEDULER_STATE_BUSY'}});release();assert.equal((await first).status,200);assert.equal(e.clients.length,1);assert.equal(e.calls.filter(x=>x===core.READ_SQL).length,1);}finally{release?.();await e.finish();}});
for(const reason of ['missing','acl','type'])test('catalog '+reason+' stops before state SELECT with rollback and no DDL',async()=>{const e=fixture();try{e.authorize();e.catalog=catalog();if(reason==='missing')e.catalog[0].kind=null;else if(reason==='acl')e.catalog[0].readable=false;else e.catalog[0].columns[0].oid=25;const r=await e.read();assert.equal(r.status,503);assert.equal(r.body.error,({missing:'SCHEDULER_STATE_DEPENDENCY_MISSING',acl:'SCHEDULER_STATE_ACL_REFUSED',type:'SCHEDULER_STATE_SCHEMA_REFUSED'})[reason]);assert.equal(e.calls.includes(core.READ_SQL),false);assert.ok(e.calls.includes(core.ROLLBACK));e.time+=600001;assert.strictEqual(await e.read(),r);assert.equal(e.clients.length,1);assertNoSecrets(r);}finally{await e.finish();}});
