for(const phase of [core.BEGIN,core.CATALOG_SQL,core.READ_SQL,'end'])test('revocation during '+(phase==='end'?'end':phase===core.READ_SQL?'state':phase===core.CATALOG_SQL?'catalog':'begin')+' suppresses the completed result',async()=>{const e=fixture();try{e.authorize();if(phase==='end')e.onEnd=()=>{e.revoked=true;};else e.onQuery=sql=>{if(sql===phase)e.revoked=true;};await assert.rejects(e.read(),{code:'SCHEDULER_STATE_BINDING_CHANGED'});e.revoked=false;const cached=await e.read();assert.equal(cached.status,409);assertNoSecrets(cached);assert.equal(e.clients.length,1);}finally{await e.finish();}});
