test('consent for another connection cannot authorize the native token current connection',async()=>{const e=fixture();try{e.authorize(CID2);await assert.rejects(e.read(),{code:'SCHEDULER_STATE_SEPARATE_CONSENT_REQUIRED'});assert.deepEqual(e.calls,[]);}finally{await e.finish();}});
test('operator uses protected connection-list POST and one explicit authorization, without state read',async()=>{
 const html=renderSchedulerStateOperator({csrf:'</script><script>bad</script>',connections:[{id:CID,label:'secret-not-rendered'}]});
 assert.ok(!html.includes('</script><script>bad'));assert.ok(!html.includes('secret-not-rendered'));assert.ok(html.includes('/auth/scheduler-state.js'));assert.equal((html.match(/<button/g)||[]).length,1);
 const calls=[],elements={'scheduler-state-authorization':{addEventListener:(event,f)=>{elements.submit=f;}},authorize:{disabled:false},result:{textContent:''},'scheduler-state-data':{textContent:JSON.stringify({csrf:'fixture-csrf'})},connection:{value:CID,replaceChildren(){this.value='';},append(option){if(!this.value)this.value=option.value;}}};
 vm.runInNewContext(SCHEDULER_STATE_JS,{document:{getElementById:id=>elements[id],createElement:()=>({})},fetch:async(path,options)=>{calls.push({path,options});return {status:200,json:async()=>({connections:[{id:CID,revoked:false,scopes:['crm.read'],brands:['fish','aristo']}]})};}});
 await new Promise(setImmediate);assert.equal(calls.length,1);assert.equal(calls[0].path,'/auth/native-connections');assert.equal(calls[0].options.method,'POST');assert.equal(calls[0].options.headers['X-CSRF-Token'],'fixture-csrf');assert.deepEqual(JSON.parse(calls[0].options.body),{action:'list'});assert.equal(elements.authorize.disabled,false);
 await elements.submit({preventDefault(){}});await elements.submit({preventDefault(){}});assert.equal(calls.length,2);assert.equal(calls[1].path,'/auth/scheduler-state-settings');assert.equal(calls[1].options.method,'POST');assert.deepEqual(JSON.parse(calls[1].options.body),{action:'authorize',connectionId:CID,consent:true});assert.doesNotMatch(SCHEDULER_STATE_JS,/scheduler-state-receipt|api\/scheduler-state|setInterval|setTimeout/);
});

test('v2 stored identity is bounded and frozen while all operational claims remain false',async()=>{const e=fixture();try{e.authorize();const r=await e.read();assert.equal(r.status,200);assert.deepEqual(r.body.storedIdentity,storedIdentity());assert.equal(r.body.schema,'shrigma-original-scheduler-stored-state-v6');assert.ok(Object.isFrozen(r.body.storedIdentity));assert.deepEqual(Object.keys(r.body.storedIdentity).sort(),['expiresAt','heartbeatAt','instanceId','runtimeSha256','workerSha256']);for(const key of ['runtimeMeasured','causeEstablished','authorizesSend','authorizesRecovery','operational'])assert.equal(r.body[key],false);assertNoSecrets(r);}finally{await e.finish();}});
test('absent lease requires null stored identity and can return other stored state without identity claims',async()=>{const e=fixture();try{e.authorize();e.payload=payload();e.payload.lease={present:false,live:null,suspended:null,reason:null};e.payload.deploymentLeaseMatch={worker:null,runtime:null,databaseRole:null};e.payload.storedIdentity=null;const r=await e.read();assert.equal(r.status,200);assert.equal(r.body.storedIdentity,null);assert.equal(r.body.deployment.present,true);assert.equal(r.body.runtimeMeasured,false);}finally{await e.finish();}});
for(const [name,change] of [
 ['missing identity',p=>{delete p.storedIdentity;}],['null present identity',p=>{p.storedIdentity=null;}],
 ['unknown identity field',p=>{p.storedIdentity.role='private-role';}],['missing identity field',p=>{delete p.storedIdentity.expiresAt;}],
 ['short worker hash',p=>{p.storedIdentity.workerSha256='a'.repeat(63);}],['uppercase runtime hash',p=>{p.storedIdentity.runtimeSha256='A'.repeat(64);}],
 ['wrong hash type',p=>{p.storedIdentity.workerSha256=true;}],['nil UUID',p=>{p.storedIdentity.instanceId='00000000-0000-0000-0000-000000000000';}],
 ['malformed UUID',p=>{p.storedIdentity.instanceId='private-caller-instance';}],['uppercase UUID',p=>{p.storedIdentity.instanceId='A1111111-1111-4111-8111-111111111111';}],
 ['invalid calendar timestamp',p=>{p.storedIdentity.heartbeatAt='2026-02-30T13:23:00Z';}],['invalid negative offset',p=>{p.storedIdentity.expiresAt='2026-10-09T13:24:00-99:00';}],
 ['non ISO timestamp',p=>{p.storedIdentity.heartbeatAt='Oct 09 2026';}],['expires before heartbeat',p=>{p.storedIdentity.expiresAt='2026-10-09T13:22:00Z';}],
 ['live disagrees with expired identity',p=>{p.lease.live=true;}],['identity for absent lease',p=>{p.lease={present:false,live:null,suspended:null,reason:null};p.deploymentLeaseMatch={worker:null,runtime:null,databaseRole:null};}]
])test('stored identity '+name+' is refused, closed and never retried',async()=>{const e=fixture();try{e.authorize();e.payload=payload();change(e.payload);const r=await e.read();assert.deepEqual(r,{status:503,body:{error:'SCHEDULER_STATE_PROTOCOL_REFUSED'}});assert.ok(e.calls.includes(core.ROLLBACK));assert.equal(e.calls.at(-1),'end');assertNoSecrets(r);e.time+=600001;assert.strictEqual(await e.read(),r);assert.equal(e.clients.length,1);}finally{await e.finish();}});
test('stored lease liveness respects microseconds and equivalent timezone offsets at exact boundaries',()=>{
 const p=payload();p.checkedAt='2026-10-09T13:25:00.000001Z';p.storedIdentity.heartbeatAt='2026-10-09T12:25:00.000000-01:00';p.storedIdentity.expiresAt='2026-10-09T13:25:00.000002Z';p.lease.live=true;assert.equal(core.validateState(p).lease.live,true);
 p.storedIdentity.expiresAt='2026-10-09T13:25:00.000001+00:00';assert.throws(()=>core.validateState(p),{code:'SCHEDULER_STATE_PROTOCOL_REFUSED'});p.lease.live=false;assert.equal(core.validateState(p).lease.live,false);
 p.storedIdentity.heartbeatAt='2026-10-09T13:25:00.000002Z';assert.throws(()=>core.validateState(p),{code:'SCHEDULER_STATE_PROTOCOL_REFUSED'});
 // Original CHECK permits a zero-length stored lease; its live predicate is false.
 p.storedIdentity.heartbeatAt=p.checkedAt;p.storedIdentity.expiresAt=p.checkedAt;p.lease.live=false;assert.equal(core.validateState(p).lease.live,false);p.lease.live=true;assert.throws(()=>core.validateState(p),{code:'SCHEDULER_STATE_PROTOCOL_REFUSED'});
});
