test('v3 dependency READ retains sanitized metadata and shapes without helpers or activity privilege',async()=>{const e=fixture();try{e.authorize();const r=await e.read(),d=r.body.scannerDependencies;assert.equal(r.status,200);assert.equal(r.body.schema,'shrigma-original-scheduler-stored-state-v6');assert.equal(d.workerRoleKnown,true);assert.equal(d.rowShapes.observedCount,2);assert.equal(d.rowShapes.helperContextEvaluated,false);assert.equal(d.nextCampaignsExecuted,false);assert.deepEqual(d.activity,{status:'unavailable',reason:'not-visible'});assert.equal(e.calls.includes(core.ACTIVITY_SQL),false);assertNoSecrets(r);assert.ok(Object.isFrozen(d.relations[0].columns[0]));assert.ok(Object.isFrozen(d.rowShapes.targets));for(const sql of [core.DEPENDENCY_SQL,core.SHAPES_SQL,core.ACTIVITY_SQL])assert.doesNotMatch(sql,/\b(?:UPDATE|INSERT|DELETE|EXPLAIN|SET\s+ROLE)\s+(?!')/i);}finally{await e.finish();}});
for(const gate of ['relation-missing','schema-incompatible','row-security','not-readable'])test('v3 '+gate+' yields bounded dependency result and never shapes SELECT',async()=>{const e=fixture();try{e.authorize();e.dependencies=dependencies();const c=e.dependencies.relations.find(r=>r.name==='campaigns');if(gate==='relation-missing'){c.present=false;c.kind='absent';c.rowSecurity=null;c.forcedRowSecurity=null;c.allCampaignColumnsSelect=false;for(const v of c.columns){v.present=false;v.typeCompatible=false;v.readerSelect=false;v.workerSelect=false;if(v.workerUpdate!==null)v.workerUpdate=false;}}else if(gate==='schema-incompatible')c.columns.find(v=>v.name==='headers').typeCompatible=false;else if(gate==='row-security')c.rowSecurity=true;else c.columns.find(v=>v.name==='headers').readerSelect=false;const r=await e.read();assert.equal(r.status,200);assert.equal(r.body.scannerDependencies.rowShapes.status,gate);assert.equal(e.calls.includes(core.SHAPES_SQL),false);assert.equal(r.body.causeEstablished,false);assertNoSecrets(r);}finally{await e.finish();}});
test('v3 worker ACL denial and missing function remain explicit, never impersonate worker',async()=>{const e=fixture();try{e.authorize();e.dependencies=dependencies();e.dependencies.relations.find(r=>r.name==='subscriber_lists').columns[0].workerSelect=false;const fn=e.dependencies.functions[0];Object.assign(fn,{present:false,signatureCompatible:false,workerExecute:false,volatility:null,securityDefiner:null});const r=await e.read();assert.equal(r.status,200);assert.equal(r.body.scannerDependencies.functions[0].present,false);assert.equal(r.body.scannerDependencies.relations.find(r=>r.name==='subscriber_lists').columns[0].workerSelect,false);assert.equal(r.body.causeEstablished,false);}finally{await e.finish();}});
test('v3 optional activity reports only bounded counts enums and age, never query pid role',async()=>{const e=fixture();try{e.authorize();e.dependencies=dependencies();e.dependencies.activityCapability.visible=true;const r=await e.read();assert.equal(r.status,200);const a=r.body.scannerDependencies.activity;assert.equal(a.status,'observed');assert.equal(a.scannerPrefixMatchCount,1);assert.equal(a.match,'fixed-prefix-only');assert.equal(a.maxPrefixAgeSeconds,10);assert.equal(e.calls.filter(x=>x===core.ACTIVITY_SQL).length,1);assert.ok(Object.isFrozen(a.states[0]));assertNoSecrets(r);assert.doesNotMatch(JSON.stringify(a),/query|pid|role/i);}finally{await e.finish();}});
