for(const variant of ['draft-only','operation','operation-ab','unknown'])test('v6 UPDATE guard '+variant+' is metadata only and not a claim of cause',async()=>{const e=fixture();try{e.authorize();e.fence=selectorFence();e.fence.sameRole=true;e.fence.updateGuard.variant=variant;e.fence.updateGuard.actualProsrcSha256=core.SEND_GUARD_HASHES[variant]||H('unknown-guard');e.fence.updateGuard.actualProsrcBytes=core.SEND_GUARD_BODY_BYTES[variant]||123;const r=await e.read();assert.equal(r.body.selectorDiagnostic.updateGuard.variant,variant);assert.equal(r.body.selectorDiagnostic.deliveryControl.status,'observed');assert.equal(r.body.causeEstablished,false);assertNoSecrets(r);}finally{await e.finish();}});
for(const change of [v=>v.targets[0].enabled='private-content',v=>v.targets[1]=v.targets[0],v=>v.targets[0].body='private-content',v=>v.targets[0].enabled=null])test('v6 malformed aggregate projection is refused and rolled back',async()=>{const e=fixture();try{e.authorize();e.fence=selectorFence();e.fence.sameRole=true;e.deliveryPayload=deliveryPayload();change(e.deliveryPayload);const r=await e.read();assert.equal(r.status,503);assert.ok(e.calls.includes(core.ROLLBACK));assertNoSecrets(r);}finally{await e.finish();}});
test('v6 absent targets and absent native count retain nulls rather than invented zero',()=>{const v=selectorPayload();v.targets[0]={id:171,eligible:false,contextReady:null,bound:null,templateCompatible:null,mediaCompatible:null,countPresent:null,countWithinInt32:null,eligibleCount:null,cursorCompatible:null};v.targets[1].countPresent=false;v.targets[1].countWithinInt32=null;v.targets[1].eligibleCount=null;v.targets[1].cursorCompatible=null;assert.equal(core.validateSelector(v).targets[0].eligible,false);});

test('v6 55000 retains direct bounded gates without claiming the false gate caused the scanner error',async()=>{const e=fixture();try{e.authorize();e.fence=selectorFence();e.fence.sameRole=true;e.contextGates=contextGates();Object.assign(e.contextGates.targets[0],{bindingPresent:true,boundEffective:true,...Object.fromEntries(core.CONTEXT_FLAGS.map(k=>[k,true])),configFresh:false});e.sqlstate='55000';const r=await e.read();assert.equal(r.body.selectorDiagnostic.deliveryControl.sqlstate,'55000');assert.equal(r.body.selectorDiagnostic.contextGates.targets[0].configFresh,false);assert.equal(r.body.selectorDiagnostic.contextGates.targets[0].selectionFresh,true);assert.equal(r.body.causeEstablished,false);assertNoSecrets(r);}finally{await e.finish();}});

test('v6 asynchronous PostgreSQL error ACK is confirmed before rollback and release',async()=>{const e=fixture();try{e.authorize();e.fence=selectorFence();e.fence.sameRole=true;e.sqlstate='55000';e.lateErrorACK=true;const r=await e.read();assert.equal(r.status,200);assert.equal(r.body.selectorDiagnostic.deliveryControl.sqlstate,'55000');assert.equal(r.body.selectorDiagnostic.rollbackConfirmed,true);}finally{await e.finish();}});
for(const missing of ['query-never-settles','known-error-without-ACK'])test('v6 12s context bounds '+missing+' without inventing rollback confirmation',async t=>{const e=fixture();let entered;const waiting=new Promise(r=>entered=r);try{e.authorize();e.fence=selectorFence();e.fence.sameRole=true;if(missing==='known-error-without-ACK'){e.sqlstate='55000';e.missingErrorACK=true;}e.onQuery=sql=>{if(sql===core.DELIVERY_CONTROL_SQL){entered();if(missing==='query-never-settles')return new Promise(()=>{});}};t.mock.timers.enable({apis:['setTimeout']});const first=e.read();await waiting;await new Promise(setImmediate);t.mock.timers.tick(12001);const r=await first;assert.equal(r.status,503);assert.equal(r.body.selectorDiagnostic,undefined);assert.equal(e.calls.includes(core.ROLLBACK),false);assert.equal(e.calls.at(-1),'end');e.time+=600001;assert.strictEqual(await e.read(),r);assert.equal(e.clients.length,1);}finally{t.mock.timers.reset();await e.finish();}});
test('v6 fence DTO identifies the exact pinned helper and transitive relation mismatch',async()=>{const e=fixture();try{e.authorize();e.fence=selectorFence();e.fence.sameRole=true;const f=e.fence.helpers.find(f=>f.name==='selection_lists_valid');f.purePin=false;f.matches.kind=false;e.fence.relations.find(r=>r.name==='config').compatible=false;const r=await e.read();assert.equal(r.body.selectorDiagnostic.fence.helpers.find(f=>f.name==='selection_lists_valid').purePin,false);assert.equal(r.body.selectorDiagnostic.fence.relations.find(r=>r.name==='config').compatible,false);assert.equal(e.calls.includes(core.SELECTOR_SQL),false);assert.equal(e.calls.includes(core.CONTEXT_GATES_SQL),false);assertNoSecrets(r);}finally{await e.finish();}});

// v5 cases exercise only new metadata/direct-gate behaviour.
function mismatch(e,flag='body'){e.fence=selectorFence();e.fence.sameRole=true;const f=e.fence.helpers.find(f=>f.name==='selection_context');f.matches[flag]=false;f.purePin=false;if(flag==='body'){f.actualProsrcSha256=H('synthetic-different-installed-body');f.actualProsrcBytes+=3;}return f;}
for(const flag of core.PURE_PIN_FIELDS)test('v5 independently identifies '+flag+' mismatch while direct context reads once without any helper',async()=>{const e=fixture();try{e.authorize();const f=mismatch(e,flag);e.contextGates=contextGates();Object.assign(e.contextGates.targets[0],{bindingPresent:true,boundEffective:true,...Object.fromEntries(core.CONTEXT_FLAGS.map(k=>[k,true])),configFresh:false});const r=await e.read(),d=r.body.selectorDiagnostic,m=d.fence.helpers.find(x=>x.name===f.name);assert.equal(r.status,200);assert.equal(r.body.schema,'shrigma-original-scheduler-stored-state-v6');assert.equal(d.reason,'helper-pin-mismatch');assert.equal(d.executed,false);assert.equal(m.matches[flag],false);assert.equal(core.PURE_PIN_FIELDS.filter(k=>!m.matches[k]).length,1);assert.equal(m.actualProsrcSha256,f.actualProsrcSha256);assert.equal(m.actualProsrcBytes,f.actualProsrcBytes);assert.equal(d.contextGates.targets[0].configFresh,false);assert.equal(d.contextGates.targets[0].selectionFresh,true);assert.equal(d.rollbackConfirmed,true);assert.equal(d.endConfirmed,true);assert.equal(e.calls.filter(x=>x===core.CONTEXT_GATES_SQL).length,1);assert.equal(e.calls.includes(core.SELECTOR_SQL),false);assert.equal(r.body.causeEstablished,false);assert.ok(Object.isFrozen(m.matches));assertNoSecrets(r);e.time+=600001;assert.strictEqual(await e.read(),r);assert.equal(e.clients.length,1);}finally{await e.finish();}});
for(const kind of ['same-role','relation-missing','relation-type','relation-acl','column-missing','column-type','column-acl','row-security','all-column-acl'])test('v5 '+kind+' denies direct context despite helper mismatch',async()=>{const e=fixture();try{e.authorize();mismatch(e);e.dependencies=dependencies();const relation=e.fence.relations.find(r=>r.name==='config'),campaign=e.dependencies.relations.find(r=>r.name==='campaigns');if(kind==='same-role')e.fence.sameRole=false;if(kind==='relation-missing'){relation.present=false;relation.compatible=false;relation.readable=false;}if(kind==='relation-type')relation.compatible=false;if(kind==='relation-acl')relation.readable=false;if(kind==='column-missing'){campaign.columns[0].present=false;campaign.columns[0].typeCompatible=false;campaign.columns[0].readerSelect=false;campaign.columns[0].workerSelect=false;}if(kind==='column-type')campaign.columns[0].typeCompatible=false;if(kind==='column-acl')campaign.columns[0].readerSelect=false;if(kind==='row-security')campaign.rowSecurity=true;if(kind==='all-column-acl')campaign.allCampaignColumnsSelect=false;const r=await e.read();assert.equal(r.status,200);assert.equal(r.body.selectorDiagnostic.contextGates,null);assert.equal(r.body.selectorDiagnostic.executed,false);assert.equal(e.calls.includes(core.CONTEXT_GATES_SQL),false);assert.equal(e.calls.includes(core.SELECTOR_SQL),false);assert.ok(e.calls.includes(core.ROLLBACK));assertNoSecrets(r);}finally{await e.finish();}});
for(const field of ['profileRevision','credentialBindingHash','crmBindingHash'])test('v5 CURRENT '+field+' revocation during unverified-helper direct read suppresses metadata and stays consumed',async()=>{const e=fixture();try{e.authorize();mismatch(e);e.onQuery=sql=>{if(sql===core.CONTEXT_GATES_SQL)e.mod[field]=H('late-revocation');};await assert.rejects(e.read(),{code:'SCHEDULER_STATE_BINDING_CHANGED'});delete e.mod[field];const n=e.calls.length;assert.equal((await e.read()).status,409);assert.equal(e.calls.length,n);assert.equal(e.calls.includes(core.SELECTOR_SQL),false);}finally{await e.finish();}});
for(const [name,change] of [['uppercase hash',f=>f.actualProsrcSha256=f.actualProsrcSha256.toUpperCase()],['non-hash',f=>f.actualProsrcSha256='private-content'],['negative bytes',f=>f.actualProsrcBytes=-1],['overflow bytes',f=>f.actualProsrcBytes=2147483648],['fractional bytes',f=>f.actualProsrcBytes=1.5],['unknown matches field',f=>f.matches.source='private-source'],['nonboolean match',f=>f.matches.language='plpgsql'],['aggregate contradiction',f=>f.purePin=true],['body contradiction',f=>f.matches.body=true]])test('v5 malformed '+name+' refuses bounded DTO before direct read and consumes attempt',async()=>{const e=fixture();try{e.authorize();const f=mismatch(e);change(f);const r=await e.read();assert.equal(r.status,503);assert.equal(r.body.error,'SCHEDULER_STATE_PROTOCOL_REFUSED');assert.equal(e.calls.includes(core.CONTEXT_GATES_SQL),false);assert.equal(e.calls.includes(core.SELECTOR_SQL),false);assertNoSecrets(r);e.time+=600001;assert.strictEqual(await e.read(),r);}finally{await e.finish();}});
test('v5 absent helper carries null hash/bytes and false flags without blocking safe direct flags',async()=>{const e=fixture();try{e.authorize();const f=mismatch(e);Object.assign(f,{present:false,executable:false,actualProsrcSha256:null,actualProsrcBytes:null,matches:Object.fromEntries(core.PURE_PIN_FIELDS.map(k=>[k,false]))});const r=await e.read();assert.equal(r.status,200);assert.equal(r.body.selectorDiagnostic.reason,'helper-missing');assert.ok(r.body.selectorDiagnostic.contextGates);assert.equal(e.calls.includes(core.SELECTOR_SQL),false);}finally{await e.finish();}});
test('v5 unknown guard returns only digest/bytes and never executes guard or unverified helper',async()=>{const e=fixture();try{e.authorize();mismatch(e);Object.assign(e.fence.updateGuard,{variant:'unknown',actualProsrcSha256:H('unknown-installed-guard'),actualProsrcBytes:5000});const r=await e.read(),g=r.body.selectorDiagnostic.updateGuard;assert.equal(r.status,200);assert.equal(g.variant,'unknown');assert.equal(g.actualProsrcBytes,5000);assert.match(g.actualProsrcSha256,/^[a-f0-9]{64}$/);assert.equal(e.calls.includes(core.SELECTOR_SQL),false);assertNoSecrets(r);}finally{await e.finish();}});
for(const fault of ['rollback-ACK','end-fail','direct-ACK'])test('v5 '+fault+' suppresses direct metadata and never retries',async()=>{const e=fixture();try{e.authorize();mismatch(e);if(fault==='rollback-ACK')e.badStatusSQL=core.ROLLBACK;if(fault==='end-fail')e.endError=true;if(fault==='direct-ACK')e.badStatusSQL=core.CONTEXT_GATES_SQL;const r=await e.read();assert.equal(r.status,503);assert.equal(r.body.selectorDiagnostic,undefined);assertNoSecrets(r);const n=e.calls.length;e.time+=600001;assert.strictEqual(await e.read(),r);assert.equal(e.calls.length,n);assert.equal(e.clients.length,1);}finally{await e.finish();}});
test('v5 direct context is single-flight and no second metadata/SELECT is created',async()=>{const e=fixture();let release,entered;const hold=new Promise(r=>release=r),pending=new Promise(r=>entered=r);try{e.authorize();mismatch(e);e.onQuery=async sql=>{if(sql===core.CONTEXT_GATES_SQL){entered();await hold;}};const first=e.read();await pending;assert.equal((await e.read()).status,409);release();assert.equal((await first).status,200);assert.equal(e.calls.filter(x=>x===core.CONTEXT_GATES_SQL).length,1);assert.equal(e.calls.includes(core.SELECTOR_SQL),false);}finally{release?.();await e.finish();}});

// V6 direct queries do not invoke the selector, guard or composed helpers.
function deliveryFence(){const row=name=>({name,present:true,compatible:true,readable:true});return {relations:Object.keys(core.DELIVERY_COLUMNS).map(row),snapshotRelations:core.MATERIAL_RELATIONS.map(row),timeZoneUtc:true};}
function deliveryPayload(){return {checkedAt:'2026-10-09T13:25:00.000Z',targets:[171,174].map(id=>({id,campaignObserved:true,controlPresent:true,...Object.fromEntries(core.DELIVERY_FLAGS.map(k=>[k,k==='suspended'?false:k==='materialMatches'?null:true]))}))};}
function deliveryMaterial(){return {checkedAt:'2026-10-09T13:25:00.000Z',timeZoneUtc:true,targets:[171,174].map(id=>({id,materialMatches:true}))};}
function composedFence(e){mismatch(e);for(const [name,p] of Object.entries(core.COMPOSED_BODY_PINS)){const f=name==='campaign_send_guard'?e.fence.updateGuard:e.fence.helpers.find(h=>h.name===name);f.actualProsrcSha256=p.sha256;f.actualProsrcBytes=p.bytes;if(name==='campaign_send_guard')f.variant='operation-ab';else{f.matches.body=f.actualProsrcSha256===core.SELECTOR_FUNCTIONS.find(h=>h.name===name).prosrcSha256&&f.actualProsrcBytes===core.SELECTOR_BODY_BYTES[name];f.purePin=Object.values(f.matches).every(x=>x);}}}
test('v6 composed provenance matches seven bodies without opening pure selector or invoking any helper',async()=>{const e=fixture();try{e.authorize();composedFence(e);const r=await e.read(),d=r.body.selectorDiagnostic,c=d.deliveryControl;assert.equal(r.status,200);assert.equal(d.reason,'helper-pin-mismatch');assert.equal(d.executed,false);assert.ok(d.composedSources.every(x=>x.present&&x.matches));assert.equal(d.updateGuard.variant,'operation-ab');assert.equal(c.status,'observed');assert.equal(c.timeZoneUtc,true);assert.equal(c.materialEvaluated,true);assert.ok(c.targets.every(t=>t.materialMatches));assert.equal(c.rollbackConfirmed,true);assert.equal(c.endConfirmed,true);assert.ok(Object.isFrozen(c.targets[0]));assert.equal(e.calls.includes(core.SELECTOR_SQL),false);assert.deepEqual(e.calls.slice(-5),[core.DELIVERY_FENCE_SQL,core.DELIVERY_CONTROL_SQL,core.DELIVERY_MATERIAL_SQL,core.ROLLBACK,'end']);assertNoSecrets(r);}finally{await e.finish();}});
for(const flag of core.DELIVERY_FLAGS.filter(k=>k!=='materialMatches'))test('v6 direct flag '+flag+' retains bounded false without inventing cause',async()=>{const e=fixture();try{e.authorize();composedFence(e);e.deliveryPayload=deliveryPayload();e.deliveryPayload.targets[0][flag]=flag==='suspended'?true:false;if(flag==='leaseLive')e.deliveryPayload.targets[0].leaseAvailable=false;const r=await e.read();assert.equal(r.status,200);assert.equal(r.body.selectorDiagnostic.deliveryControl.targets[0][flag],flag==='suspended'?true:false);assert.equal(r.body.causeEstablished,false);assert.equal(r.body.authorizesRecovery,false);assert.equal(r.body.authorizesSend,false);assert.equal(e.calls.includes(core.SELECTOR_SQL),false);}finally{await e.finish();}});
test('v6 absent control keeps every control flag null while campaign presence is independently observed',async()=>{const e=fixture();try{e.authorize();composedFence(e);e.deliveryPayload=deliveryPayload();e.deliveryMaterial=deliveryMaterial();for(const t of e.deliveryPayload.targets){t.controlPresent=false;for(const k of core.DELIVERY_FLAGS)t[k]=null;}e.deliveryPayload.targets[1].campaignObserved=false;for(const t of e.deliveryMaterial.targets)t.materialMatches=null;const r=await e.read();assert.equal(r.status,200);for(const t of r.body.selectorDiagnostic.deliveryControl.targets){assert.equal(t.controlPresent,false);for(const k of core.DELIVERY_FLAGS)assert.equal(t[k],null);}}finally{await e.finish();}});
for(const state of [false,null])test('v6 UTC '+state+' is unknown material not false and never changes session config',async()=>{const e=fixture();try{e.authorize();composedFence(e);e.deliveryFence=deliveryFence();e.deliveryFence.timeZoneUtc=state;const r=await e.read(),c=r.body.selectorDiagnostic.deliveryControl;assert.equal(c.timeZoneUtc,state);assert.equal(c.materialEvaluated,false);assert.equal(c.materialReason,'utc-unverified');assert.ok(c.targets.every(x=>x.materialMatches===null));assert.equal(e.calls.includes(core.DELIVERY_MATERIAL_SQL),false);assert.ok(e.calls.includes(core.DELIVERY_CONTROL_SQL));}finally{await e.finish();}});
for(const [name,flag] of [['regular_delivery_campaign','present'],['regular_delivery_campaign','compatible'],['regular_delivery_campaign','readable'],['media','present'],['media','compatible'],['media','readable'],['templates','readable'],['lists','compatible']])test('v6 '+name+' '+flag+' fence prevents unsafe direct/material reference',async()=>{const e=fixture();try{e.authorize();composedFence(e);e.deliveryFence=deliveryFence();const row=e.deliveryFence.relations.find(x=>x.name===name)||e.deliveryFence.snapshotRelations.find(x=>x.name===name);row[flag]=false;if(flag==='present'){row.compatible=false;row.readable=false;}const r=await e.read(),c=r.body.selectorDiagnostic.deliveryControl;assert.equal(r.status,200);if(name==='regular_delivery_campaign'){assert.equal(c.status,'refused');assert.equal(c.targets,null);assert.equal(e.calls.includes(core.DELIVERY_CONTROL_SQL),false);}else{assert.equal(c.status,'observed');assert.ok(c.targets.every(x=>x.materialMatches===null));}assert.equal(e.calls.includes(core.DELIVERY_MATERIAL_SQL),false);assert.equal(e.calls.includes(core.SELECTOR_SQL),false);}finally{await e.finish();}});
for(const [name,change] of [['leak',p=>p.targets[0].material='private-content'],['duplicate',p=>p.targets[1]=p.targets[0]],['inconsistent-live',p=>{p.targets[0].leaseLive=false;p.targets[0].leaseAvailable=true;}],['null-present',p=>p.targets[0].enabled=null],['nonboolean',p=>p.targets[0].bindingMatches='private-role']])test('v6 malformed control '+name+' suppresses receipt and remains terminal',async()=>{const e=fixture();try{e.authorize();composedFence(e);e.deliveryPayload=deliveryPayload();change(e.deliveryPayload);const r=await e.read();assert.equal(r.status,503);assert.equal(r.body.error,'SCHEDULER_STATE_PROTOCOL_REFUSED');assertNoSecrets(r);assert.ok(e.calls.includes(core.ROLLBACK));e.time+=600001;assert.strictEqual(await e.read(),r);assert.equal(e.clients.length,1);}finally{await e.finish();}});
for(const phase of [core.DELIVERY_FENCE_SQL,core.DELIVERY_CONTROL_SQL,core.DELIVERY_MATERIAL_SQL,'end'])test('v6 CURRENT revocation during '+(phase==='end'?'closure':phase===core.DELIVERY_FENCE_SQL?'delivery-fence':phase===core.DELIVERY_CONTROL_SQL?'delivery-control':'delivery-material')+' suppresses result without retry',async()=>{const e=fixture();try{e.authorize();composedFence(e);if(phase==='end')e.onEnd=()=>{e.revoked=true;};else e.onQuery=s=>{if(s===phase)e.revoked=true;};await assert.rejects(e.read(),{code:'SCHEDULER_STATE_BINDING_CHANGED'});e.revoked=false;assert.equal((await e.read()).status,409);assert.equal(e.clients.length,1);}finally{await e.finish();}});
test('v6 UTC changes before material evaluation retain null and explicit unknown',async()=>{const e=fixture();try{e.authorize();composedFence(e);e.deliveryMaterial=deliveryMaterial();e.deliveryMaterial.timeZoneUtc=false;for(const t of e.deliveryMaterial.targets)t.materialMatches=null;const r=await e.read(),d=r.body.selectorDiagnostic.deliveryControl;assert.equal(d.timeZoneUtc,false);assert.equal(d.materialEvaluated,false);assert.equal(d.materialReason,'utc-unverified');assert.ok(d.targets.every(x=>x.materialMatches===null));}finally{await e.finish();}});
test('v6 material true/false is bounded and never returns snapshot values',async()=>{const e=fixture();try{e.authorize();composedFence(e);e.deliveryMaterial=deliveryMaterial();e.deliveryMaterial.targets[0].materialMatches=false;const r=await e.read();assert.deepEqual(r.body.selectorDiagnostic.deliveryControl.targets.map(t=>t.materialMatches),[false,true]);assertNoSecrets(r);assert.equal(r.body.causeEstablished,false);}finally{await e.finish();}});

for(const [sql,phase] of [[core.DELIVERY_FENCE_SQL,'delivery-fence'],[core.DELIVERY_MATERIAL_SQL,'delivery-material']])test('v6 known SQLSTATE at '+phase+' confirms rollback/end and preserves earlier safe flags only',async()=>{const e=fixture();try{e.authorize();composedFence(e);e.errorSQL=sql;e.sqlstate='57014';const r=await e.read(),d=r.body.selectorDiagnostic.deliveryControl;assert.equal(r.status,200);assert.equal(d.status,'postgres-error');assert.equal(d.phase,phase);assert.equal(d.sqlstate,'57014');assert.equal(d.rollbackConfirmed,true);assert.equal(d.endConfirmed,true);assert.deepEqual(e.calls.slice(-3),[sql,core.ROLLBACK,'end']);if(phase==='delivery-material'){assert.ok(d.targets);assert.ok(d.targets.every(t=>t.materialMatches===null));}else assert.equal(d.targets,null);assert.equal(e.calls.includes(core.SELECTOR_SQL),false);assertNoSecrets(r);assert.strictEqual(await e.read(),r);}finally{await e.finish();}});
for(const change of [m=>m.targets[0].materialMatches='private-content',m=>m.targets[1]=m.targets[0],m=>m.targets[0].material='private-content',m=>{m.timeZoneUtc=false;m.targets[0].materialMatches=true;}])test('v6 malformed material projection suppresses all DTOs and never repeats',async()=>{const e=fixture();try{e.authorize();composedFence(e);e.deliveryMaterial=deliveryMaterial();change(e.deliveryMaterial);const r=await e.read();assert.equal(r.status,503);assert.equal(r.body.error,'SCHEDULER_STATE_PROTOCOL_REFUSED');assertNoSecrets(r);assert.ok(e.calls.includes(core.ROLLBACK));assert.strictEqual(await e.read(),r);}finally{await e.finish();}});

